def run(api_json, api_text, coin_id, last_price, threshold_percent, probe_status, probe_error):
    def to_num(x):
        try:
            if x is None:
                return None
            return float(x)
        except Exception:
            return None

    current = None
    err = ''
    cid = (coin_id or '').strip().lower()

    if isinstance(api_json, dict):
        coin_obj = api_json.get(cid)
        if isinstance(coin_obj, dict):
            current = to_num(coin_obj.get('usd'))
        elif len(api_json) == 1:
            only = next(iter(api_json.values()))
            if isinstance(only, dict):
                current = to_num(only.get('usd'))

    if current is None and isinstance(api_text, str):
        err = api_text[:200]

    prev = to_num(last_price)
    threshold = abs(to_num(threshold_percent) or 0)
    probe_status_num = to_num(probe_status)
    probe_err = probe_error or ''

    change_amount = None
    change_percent = None
    should_notify = False
    if current is not None and prev is not None and prev != 0:
        change_amount = current - prev
        change_percent = (change_amount / prev) * 100.0
        should_notify = abs(change_percent) > threshold
    elif current is not None:
        change_amount = 0.0 if prev is None else current - prev
        change_percent = 0.0 if prev is None else None
        should_notify = False

    api_error = err or (probe_err if current is None else '')
    return {
        'current_price': current,
        'last_price': prev,
        'change_amount': change_amount,
        'change_percent': change_percent,
        'should_notify': should_notify,
        'api_error': api_error,
        'has_price': current is not None,
        'probe_status': probe_status_num,
        'probe_error': probe_err
    }

def run(coin_id, vs_currency, current_price, last_price, change_percent, change_amount, should_notify, threshold_percent, api_error, probe_status):
    coin = coin_id or 'that coin'

    def fmt_price(x):
        if x is None:
            return 'unavailable'
        x = float(x)
        if x >= 1000:
            return f'${x:,.2f}'
        return f'${x:.6f}'.rstrip('0').rstrip('.')

    def fmt_pct(x):
        if x is None:
            return 'n/a'
        return f'{x:+.2f}%'

    def fmt_amt(x):
        if x is None:
            return 'n/a'
        return f'${x:+,.2f}'

    if current_price is None:
        speech = f'I could not read the current price for {coin}. The API did not return a usable price, so I cannot compare it yet.'
    else:
        status = 'moved beyond the threshold' if should_notify else 'is within the threshold'
        speech = f'{coin} is now {fmt_price(current_price)} USD. The change since the last check is {fmt_pct(change_percent)} or {fmt_amt(change_amount)}, and it {status} at {threshold_percent} percent.'

    report = f'''# Crypto Price Watcher

## Status
- **Coin:** {coin}
- **Current price:** {fmt_price(current_price)} USD
- **Previous price:** {fmt_price(last_price)} USD
- **Change:** {fmt_pct(change_percent)} ({fmt_amt(change_amount)})
- **Threshold:** {threshold_percent}%
- **Alert condition met:** {'yes' if should_notify else 'no'}

## API
- **Probe status:** {probe_status if probe_status is not None else 'n/a'}
- **Error:** {api_error or 'none'}
'''
    return {'speech': speech[:900], 'report': report}
